inline std::string_view electricityStatusMessageKeyName(ElectricityStatusMessageKey key){
    static constexpr std::array<std::string_view,electricityStatusMessageKeyCount> names={{"electricity.status.ok","electricity.status.partial","electricity.status.unavailable","electricity.status.invalid","electricity.status.unsupported","electricity.status.missing_price","electricity.status.conflict","electricity.status.not_yet_known","electricity.status.clock_fault","electricity.status.capacity","electricity.status.unknown"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage electricityStatusMessage(std::string_view language,ElectricityStatusMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=electricityStatusMessageKeyCount)return {};
    const auto &source=electricityStatusLocalePacks()[0];const auto *selected=&source;for(const auto &pack:electricityStatusLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string electricityStatusEnglish(ElectricityStatusMessageKey key){return std::string(electricityStatusMessage("en",key).text);}
